import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { pathToFileURL } from 'node:url';
const root = resolve('extensions/sdk-ts/node_modules/@earendil-works/pi-coding-agent');
assert.equal(JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).version, '1.1.0');
const parent = pathToFileURL(join(root, 'package.json')).href;
const { Agent } = await import(import.meta.resolve('@earendil-works/pi-agent-core', parent));
const { EventStream } = await import(import.meta.resolve('@earendil-works/pi-ai', parent));
const deferred = () => { let resolve; const promise = new Promise(r => { resolve = r; }); return { promise, resolve }; };
const started = deferred(), terminal = deferred(), ended = deferred(), release = deferred();
let signal, subscriberFinished = false, promptFinished = false;
const transcriptStates = [];
const message = { role: 'assistant', content: [{ type: 'text', text: 'partial' }], api: 'openai-responses', provider: 'openai', model: 'mock', usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0, cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } }, stopReason: 'aborted', errorMessage: 'Request was aborted', timestamp: 1 };
const agent = new Agent({ streamFn: (_model, _context, options) => {
  const stream = new EventStream(e => e.type === 'error', e => e.error);
  stream.push({ type: 'start', partial: { ...message, stopReason: 'stop', errorMessage: undefined } });
  options.signal.addEventListener('abort', () => { terminal.resolve(); queueMicrotask(() => stream.push({ type: 'error', reason: 'aborted', error: message })); });
  started.resolve();
  return stream;
}});
agent.subscribe(async (event, activeSignal) => {
  if (event.type === 'message_start' || event.type === 'message_end') transcriptStates.push(event.type + ':' + event.message.role + ':' + agent.state.messages.map(message => message.role).join(','));
  if (event.type === 'agent_start') signal = activeSignal;
  if (event.type === 'agent_end') { ended.resolve(); await release.promise; subscriberFinished = true; }
});
const prompt = agent.prompt('abort me').then(() => { promptFinished = true; });
await started.promise;
assert.equal(signal.aborted, false);
agent.abort();
await terminal.promise;
await ended.promise;
assert.equal(signal.aborted, true);
assert.equal(promptFinished, false);
assert.equal(subscriberFinished, false);
