const errorOf = async operation => { try { await operation(); } catch (error) { return error.message; } throw new Error('expected rejection'); };
const errors = [await errorOf(() => agent.prompt('busy')), await errorOf(() => agent.continue()), await errorOf(() => agent.reset())];
const last = agent.state.messages.at(-1);
console.log('AGENT_LIFECYCLE held ' + JSON.stringify([last.stopReason, last.errorMessage, agent.state.errorMessage, signal.aborted, promptFinished]));
const idle = agent.waitForIdle();
release.resolve();
await Promise.all([prompt, idle]);
console.log('AGENT_LIFECYCLE settled ' + JSON.stringify([subscriberFinished, promptFinished, agent.state.isStreaming, [...agent.state.pendingToolCalls]]));
const empty = new Agent({ streamFn: () => { throw new Error('unexpected stream'); } });
errors.push(await errorOf(() => empty.continue()), await errorOf(() => agent.continue()));
console.log('AGENT_LIFECYCLE errors ' + JSON.stringify(errors));
console.log('AGENT_LIFECYCLE transcript ' + JSON.stringify(transcriptStates));
console.log('AGENT_LIFECYCLE retained-error ' + JSON.stringify(agent.state.errorMessage));
const initialTools = [{ name: 'first', label: 'first', description: 'first tool', parameters: { type: 'object', properties: {} }, execute: async () => ({ content: [] }) }];
const copied = new Agent({ initialState: { tools: initialTools }, streamFn: () => { throw new Error('unexpected stream'); } });
initialTools[0] = { ...initialTools[0], name: 'second' };
console.log('AGENT_LIFECYCLE initial-tools ' + JSON.stringify([copied.state.tools[0].name, copied.state.messages[0].toolsAdded[0].name]));
